#include "stdafx.h"#include "AlarmsFile.h"#include <CommonH.h>//CAlarmsFile::CAlarmsFile(int nNumber): m_nNumber(nNumber), m_hMapData(NULL), m_pbBegWnd(NULL)//, m_dwCurrSector(0), m_pDataT(NULL){  SYSTEM_INFO SI;  GetSystemInfo( &SI );  m_dwAllocKvant = SI.dwAllocationGranularity;  m_dwCountKvant = m_dwAllocKvant/sizeof(CAlarmEntry);  ASS( m_dwAllocKvant == m_dwCountKvant*sizeof(CAlarmEntry) );}CAlarmsFile::~CAlarmsFile(){  Clear();}void CAlarmsFile::Clear(){  if ( m_pbBegWnd ) ::UnmapViewOfFile( m_pbBegWnd );m_pbBegWnd = NULL;  if ( m_hMapData ) ::CloseHandle    ( m_hMapData );m_hMapData = NULL;  m_pDataT = NULL;  m_dwCurrSector = 0;}bool CAlarmsFile::Init(){  Clear();  return OpenAlarmData();}HANDLE CAlarmsFile::HandleT(){  char szFile[_MAX_PATH];  lstrcpy ( szFile, GetAlarmFileName(m_nNumber==1) );  //  HANDLE hHandle = ::CreateFile(    szFile,    GENERIC_READ|GENERIC_WRITE,    FILE_SHARE_READ|FILE_SHARE_WRITE,//|FILE_SHARE_DELETE,    NULL,    OPEN_ALWAYS,    FILE_ATTRIBUTE_ARCHIVE,    NULL );  return hHandle;}//bool CAlarmsFile::OpenAlarmData(){  if ( m_hMapData ) ::CloseHandle( m_hMapData );  //  HANDLE hVarFile = HandleT();  if ( hVarFile != INVALID_HANDLE_VALUE )  {    char szName[32];    sprintf_s( szName, "0 Data Alarms %d", m_nNumber );    //    m_hMapData = ::CreateFileMapping( hVarFile,                                       NULL, PAGE_READWRITE ,0, m_dwAllocKvant*(m_dwCurrSector+1), szName );    if ( m_hMapData != NULL )    {      ::CloseHandle ( hVarFile );      return true;    }  }  DWORD Err = GetLastError();  ASS(FALSE);  return false;}//void CAlarmsFile::SaveAlarm( CAlarmEntry& rAlarm, int& nAlarms, THoneyWell* pHoney, CCBHSystem* pCBSystem ){  if( pHoney && !pHoney->m_pObj )    return;  if( (nAlarms % m_dwCountKvant) == 0 )  {    //CSemLock LockIniAlarms ( "Alarms access", 5000 );    // Смена окна    ::UnmapViewOfFile( m_pbBegWnd );    if ( m_pbBegWnd != NULL )    {      m_dwCurrSector++;      OpenAlarmData();    }    m_pbBegWnd = MapView( m_hMapData, m_dwCurrSector*m_dwAllocKvant, m_dwAllocKvant );    ASS(m_pbBegWnd != NULL);    m_pDataT = (CAlarmEntry*)(m_pbBegWnd);    memset( m_pDataT, 0, m_dwAllocKvant );  }  //  // До пятидесятого шага вс¸ должно быть квитировано  if( pHoney )  {    bool bQuqu = 1;    bQuqu = ( pCBSystem->nStep > eMagicStep );    rAlarm.btKvit =  bQuqu ? 0:1;    rAlarm.nTimeS = (int)pCBSystem->timeB;    rAlarm.nTimeA = (int)pCBSystem->timeM;    pHoney->m_pObj->notACK = bQuqu ? 1:0;    pHoney->m_pObj->setACK = 0;  }  //  memcpy( m_pDataT, &rAlarm, sizeof(CAlarmEntry) );  m_pDataT++;  nAlarms++;}//bool CAlarmsFile::FindAlarm(CAlarmEntry& rAlarm,int& nAlarms,THoneyWell& rHoney){  CAlarmEntry* a = (CAlarmEntry*)m_pbBegWnd;  if ( a == NULL )    return false;  for ( int N = m_dwCurrSector; N >= 0; N-- )  {    for ( int n = m_dwCountKvant-1; n >= 0; n-- )    {      if ( a[n].dwName == rAlarm.dwName )// Номер в Names.dat (уникален)        //    if ( a[n].dwType == rAlarm.dwType )// Тип объекта (хватит dwName )        if ( a[n].btType == rAlarm.btType )// Тип сигнализации        {          a[n].btOnOf = 0;          rAlarm.btEHLN = a[n].btEHLN;          return (a[n].btKvit & 0x01) == 0x01;        }    }  }  return false;}//